// Settings macros, feel free to mess around with these 

// Settings for camera
#define ZOOM_VALUE 4.0
#define X_OFFSET_VALUE 0.0
#define Y_OFFSET_VALUE 0.0

// Settings for border
#define ISOLATE true
#define ISOLATION_RADIUS 50.0

// Settings for brush
#define SQUARE_BRUSH true
#define BRUSH_SIZE 2.0

// Controls
const int KEY_0 = 48;
const int KEY_SPACE = 32;

/////////////////// CELL STUFF //////////////////////////////////////

const int ERROR_ID   =-1;
const int HELIUM_ID  = 0;
const int AIR_ID     = 1;
const int FOG_ID     = 2;
const int OIL_ID     = 3;
const int WATER_ID   = 4;
const int HONEY_ID   = 5;
const int MERCURY_ID = 6;
const int BARK_ID    = 7;
const int SAND_ID    = 8;
const int ICE_ID     = 10;
const int STONE_ID   = 9;
const int NUM_IDS    = 11;

struct Cell
{
    int id;
    float density;
    float roughness;
    float grainularity;
};

const Cell ERROR   = Cell(ERROR_ID, 0., 999., 0.);
const Cell HELIUM  = Cell(HELIUM_ID, 0.2, -1.0, 1.0); 
const Cell AIR     = Cell(AIR_ID, 1.2, -1.0, 1.0);
const Cell FOG     = Cell(FOG_ID, 1.3, -1.0, 1.0);
const Cell OIL     = Cell(OIL_ID, 800.0, -0.99, 0.99);
const Cell WATER   = Cell(WATER_ID, 1000.0, -1.0, 0.999);
const Cell HONEY   = Cell(HONEY_ID, 1420.0, 0.1, 0.99);
const Cell MERCURY = Cell(MERCURY_ID, 13000.0, -0.5, 1.0);
const Cell BARK    = Cell(BARK_ID, 400.0, 0.2, 0.2);
const Cell SAND    = Cell(SAND_ID, 1600.0, 0.1, 0.5);
const Cell ICE     = Cell(ICE_ID, 900.0, -1.0, 0.2);
const Cell STONE   = Cell(STONE_ID, 2500.0, 0.45, 0.1);

const vec4 ERROR_COLOR   = vec4(0,0,0,1);
const vec4 HELIUM_COLOR  = vec4(255, 100, 100, 255) / 255.;
const vec4 AIR_COLOR     = vec4(200, 200, 255, 255) / 255.;
const vec4 FOG_COLOR     = vec4(220, 220, 240, 255) / 255.;
const vec4 OIL_COLOR     = vec4(64,  64,  0,   255) / 255.;
const vec4 WATER_COLOR   = vec4(0,   128, 255, 255) / 255.;
const vec4 HONEY_COLOR   = vec4(255, 170, 80,  255) / 255.;
const vec4 MERCURY_COLOR = vec4(192, 192, 192, 255) / 255.;
const vec4 BARK_COLOR    = vec4(139, 69,  19,  255) / 255.;
const vec4 SAND_COLOR    = vec4(210, 180, 140, 255) / 255.;
const vec4 ICE_COLOR     = vec4(173, 216, 230, 255) / 255.;
const vec4 STONE_COLOR   = vec4(169, 169, 169, 255) / 255.;

Cell getCell(int id) {
    switch(id) {
        case HELIUM_ID:  return HELIUM;
        case AIR_ID:     return AIR;
        case FOG_ID:     return FOG;
        case OIL_ID:     return OIL;
        case WATER_ID:   return WATER;
        case HONEY_ID:   return HONEY;
        case MERCURY_ID: return MERCURY;
        case BARK_ID:    return BARK;
        case SAND_ID:    return SAND;
        case ICE_ID:     return ICE;
        case STONE_ID:   return STONE;
        default:         return ERROR;
    }
}

vec4 getCellColor(int id) {
    switch(id) {
        case HELIUM_ID:  return HELIUM_COLOR;
        case AIR_ID:     return AIR_COLOR;
        case FOG_ID:     return FOG_COLOR;
        case OIL_ID:     return OIL_COLOR;
        case WATER_ID:   return WATER_COLOR;
        case HONEY_ID:   return HONEY_COLOR;
        case MERCURY_ID: return MERCURY_COLOR;
        case BARK_ID:    return BARK_COLOR;
        case SAND_ID:    return SAND_COLOR;
        case ICE_ID:     return ICE_COLOR;
        case STONE_ID:   return STONE_COLOR;
        default:         return ERROR_COLOR;
    }
}

Cell getCell(uint id) {
    return getCell(int(id));
}

vec4 getCellColor(uint id) {
    return getCellColor(int(id));
}

/////////////////// END OF CELL STUFF //////////////////////////////////////


/////////////////// GENERAL UTILS //////////////////////////////////////////

int coordToID(sampler2D channel, ivec2 coord)
{
     return int(texelFetch(channel, coord, 0).x);
}

ivec2 coordToBlockPos(ivec2 coord, int frame)
{
    ivec2 offset = ivec2(frame % 2);
    ivec2 blockPos  = ((coord - offset) / 2) * 2 + offset;
    return blockPos;
}

ivec2 coordToRelativePos(ivec2 coord, int frame)
{
    ivec2 offset = ivec2(frame % 2);
    ivec2 relativePos = (coord - offset) % 2;
    return relativePos;
}

ivec2 worldSpacePos(ivec2 coord, ivec2 worldDim)
{
    return coord % worldDim;
}

int toIndex(ivec2 coord, ivec2 dim)
{
    int xWrapped = ((coord.x % dim.x) + dim.x) % dim.x;
    int yWrapped = ((coord.y % dim.y) + dim.y) % dim.y;

    return xWrapped + yWrapped * dim.x;
}

int relativePosToID(ivec2 relativePos, int aID, int bID, int cID, int dID)
{
    if (relativePos == ivec2(0,0))
        return aID; // id of cell A

    // horizontal symmetry
    if (relativePos == ivec2(1,0) || relativePos == ivec2(-1,0))
        return bID; // id of cell B

    // vertical symmetry
    if (relativePos == ivec2(0,1) || relativePos == ivec2(0,-1))
        return cID; // id of cell C

    // diagonal    
    return dID; // id of cell D
}
void swap(inout int a, inout int b) 
{
    int tmp = a;
    a = b;
    b = tmp;
}

// RNG
// https://www.shadertoy.com/view/WttXWX
uint rngu(uint x)
{
    x ^= x >> 17;
    x *= 0xed5ad4bbU;
    x ^= x >> 11;
    x *= 0xac4c1b51U;
    x ^= x >> 15;
    x *= 0x31848babU;
    x ^= x >> 14;
    return x;
}

// Modified to work with 4 values at once
uvec4 rng4u(uint y)
{
    uvec4 x = y * uvec4(213u, 2131u, 21313u, 213132u);
    x ^= x >> 16;
    x *= 0x7feb352dU;
    x ^= x >> 15;
    x *= 0x846ca68bU;
    x ^= x >> 16;
    y = x.x;
    return x;
}

// ChatGPT authored
uint rngu(ivec2 coord, int frame)
{
    // Mix coord components and frame together with prime-based shifts and multiplications
    uint seed = uint(coord.x) * 0x45d9f3bU;  // A large prime for x
    seed ^= uint(coord.y) * 0x9e3779b9U;    // A different large prime for y
    seed ^= uint(frame) * 0x7f4a7c15U;      // A large prime for the frame number
    seed = rngu(seed);                      // Pass through the improved rngu() function
    return seed;}

uint rngu(ivec2 coord, int frame, uint range)
{
    return rngu(coord, frame) % range;
}

float rngf(ivec2 coord, int frame)
{
    return float(rngu(coord, frame)) / 4294967295.0; // Divide by max uint value
}

// ChatGPT authored
vec4 rng4f(ivec2 coord, int frame) {
    // Combine the inputs (coord.x, coord.y, frame) with distinct primes and bit mixing
    uint seed = uint(coord.x) * 0x45d9f3bU;  // Large prime for coord.x
    seed ^= uint(coord.y) * 0x9e3779b9U;    // Large prime for coord.y
    seed ^= uint(frame) * 0x7f4a7c15U;      // Large prime for the frame number
    seed = rngu(seed);                      // Pass through the improved rngu() function

    // Generate four random uints based on the mixed seed
    uvec4 random_uints = rng4u(seed);

    // Normalize the random uints to [0, 1]
    return vec4(random_uints) / 4294967295.0; // Max value of uint
}

bool isKeyPressed(int keyID, sampler2D keyboardChannel)
{
    return texelFetch(keyboardChannel, ivec2(keyID, 0), 0).r > 0.0;
}

/////////////////// END OF GENERAL UTILS //////////////////////////////////////////


/////////////////// SIMULATION LOGIC //////////////////////////////////////////

float computeRotateChance(int aID, int bID,
                          int cID, int dID)
{
    Cell a = getCell(aID);
    Cell b = getCell(bID);
    Cell c = getCell(cID);
    Cell d = getCell(dID);

    float bcd_density = b.density + c.density; // should have + d but i like the results without
                                               // need to think of better formula lol
    if (a.density <= bcd_density)
        return 0.0;

    float density_ratio = a.density / bcd_density;

    float force_chance = 1.0 - (1.0 / density_ratio);

    float total_roughness = a.roughness + b.roughness + c.roughness + d.roughness;
    float slip_chance = 1.0 - clamp(total_roughness / 4.0, 0.0, 1.0);

    float total_grainularity = a.grainularity + b.grainularity + c.grainularity + d.grainularity;
    float slide_chance = clamp(total_grainularity - 1.0, 0.0, 1.0);

    return force_chance * slip_chance * slide_chance;
}

float computeVerticalSwapChance(int topID, int botID)
{
    Cell top = getCell(topID);
    Cell bot = getCell(botID);

    if (top.density <= bot.density)
        return 0.0;

    float density_ratio = top.density / bot.density;

    float force_chance = 1.0 - (1.0 / density_ratio);
    float diffusion_chance = clamp(top.grainularity + bot.grainularity - 1.0, 0.0, 1.0);
    float slip_chance = 1.0 - clamp(top.roughness + bot.roughness, 0.0, 1.0);

    float swap_chance = force_chance * slip_chance * diffusion_chance;
    return clamp(swap_chance, 0.0, 1.0);
}                 

float computeHorizontalSwapChance(int aID, int bID,
                                  int cID, int dID)
{
    Cell a = getCell(aID);
    Cell b = getCell(bID);
    Cell c = getCell(cID);
    Cell d = getCell(dID);

    if (aID == cID && aID == dID)
        return 0.0;

    // perform calculations in standard form
    if (a.density <= b.density && a.density <= c.density)
        return 0.0;

    float vertical_density_ratio = a.density / c.density;
    float horizontal_density_ratio = a.density / b.density;
    float mg_force = (1.0 / vertical_density_ratio);
    float spread_force = (a.grainularity / horizontal_density_ratio);
    float force_chance = mg_force + spread_force;

    float total_roughness = a.roughness + b.roughness + c.roughness + d.roughness;
    float slip_chance = 1.0 - clamp(total_roughness / 4.0, 0.0, 1.0);

    float diffusion_chance = clamp(a.grainularity + b.grainularity - 1.0, 0.0, 1.0);

    float bead_chance = force_chance * slip_chance * diffusion_chance;
    return clamp(bead_chance, 0.0, 1.0);
}

int simulate(sampler2D channel, ivec2 block, ivec2 relativePos, int frame, ivec2 worldDim)
{
    // compute cells in block
    int aID = coordToID(channel, worldSpacePos(block + ivec2(0,0), worldDim));
    int bID = coordToID(channel, worldSpacePos(block + ivec2(1,0), worldDim));
    int cID = coordToID(channel, worldSpacePos(block + ivec2(0,1), worldDim));
    int dID = coordToID(channel, worldSpacePos(block + ivec2(1,1), worldDim));

    vec4 rng = rng4f(block, frame);

    // check for cell transformations
    bool transformed = false;

    // this is just a jank hardcoded test, will be refactored and scaled
    {
        // 4 fog tiles have a chance to make 1 water 3 air
        bool isAllFog = aID == bID && aID == cID && aID == dID && aID == FOG_ID;

        if (isAllFog && rng.x < 0.01)
        {
            transformed = true;
            aID = AIR_ID;
            bID = AIR_ID;
            cID = AIR_ID;
            dID = WATER_ID;
        }
    }

    // if a cell transformation takes place, do not proceed with movement
    if (transformed)
        return relativePosToID(relativePos, aID, bID, cID, dID);

    /// check for cell movement

    // diffusion/vertical swapping
    float acSwapChance = computeVerticalSwapChance(aID, cID);
    float bdSwapChance = computeVerticalSwapChance(bID, dID);

    if (rng.x < acSwapChance)
        swap(aID, cID);

    if (rng.y < bdSwapChance)
        swap(bID, dID);

    bool moved = (rng.x < acSwapChance || rng.y < bdSwapChance); 

    // rotation
    if (!moved)
        {
            float rotateCounterChance = computeRotateChance(aID, bID,   // standard form
                                                            cID, dID);

            float rotateClockwiseChance = computeRotateChance(bID, aID, // colums swapped
                                                              dID, cID);

            int newA = aID;
            int newB = bID;
            int newC = cID;
            int newD = dID;

            if (rng.w < rotateCounterChance)
            {
                // ab => bd
                // cd    ac
                newA = bID;
                newB = dID;
                newC = aID;
                newD = cID;
            }
            else if (rng.w < rotateClockwiseChance)
            {
                // ab => ca
                // cd    db
                newA = cID;
                newB = aID;
                newC = dID;
                newD = bID;
            }

            aID = newA;
            bID = newB;
            cID = newC;
            dID = newD;

            moved = (rng.w < rotateClockwiseChance || rng.w < rotateCounterChance); 
        }

    // beading/horizontal swapping
    if (!moved)
    {
        float beadChance = max(
            computeHorizontalSwapChance(aID, bID, // standard form
                                        cID, dID), 
            computeHorizontalSwapChance(bID, aID, // colums swapped
                                        dID, cID)
            ); // note, tried taking max of row swapping and both swapping too, results werent great

        if (rng.z < beadChance)
            swap(aID, bID);
    }

    // return correct cell
    return relativePosToID(relativePos, aID, bID, cID, dID);
}

void init(out vec4 fragColor, in ivec2 coord)
{
    uint randomID = rngu(coord, iFrame, uint(NUM_IDS));
    fragColor = vec4(randomID, 0, 0, 0);
}

void doNothing(out vec4 fragColor, in ivec2 coord)
{
    int oldID = coordToID(iChannel0, coord);
    fragColor = vec4(ERROR_ID, 0, 0, 0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 coord = ivec2(fragCoord);

    if (iFrame == 0)
    {
        init(fragColor, coord);
        return;
    }

    // black out area outside of center circle if ISOLATE is turned on
    if (ISOLATE && length(fragCoord - iResolution.xy / (ZOOM_VALUE*2.0)) > ISOLATION_RADIUS)
    {
        doNothing(fragColor, coord);
        return;
    }

    ivec2 blockPos = coordToBlockPos(coord, iFrame);
    ivec2 relativePos = coordToRelativePos(coord, iFrame);
    ivec2 worldDim = ivec2(iResolution);

    int newID = simulate(iChannel0, blockPos, relativePos, iFrame, worldDim);    
    fragColor = vec4(newID, 0, 0, 0);
}

// returns the ID of the cell at coord after taking user input into account
int handleInput(ivec2 coord)
{
    int oldID = coordToID(iChannel0, coord);

    // ignore input for the first half second otherwise you draw by hitting play
    if (iFrame < 30)
        return oldID;

    // space key resets everything to air
    if (isKeyPressed(KEY_SPACE, iChannel1))
        return AIR_ID;

    // get which cell we should place from keyboard
    int newID = ERROR_ID;

    for (int i = 0; i < 10; ++i)
        if (isKeyPressed(KEY_0 + i, iChannel1))
            newID = i;

    // pass if mouse idle
    if (iMouse.z <= 0.0)
        return oldID;

    // get mouse pos after camera transform and vertical reflection
    float zoom = ZOOM_VALUE;
    vec2 offset = vec2(X_OFFSET_VALUE, Y_OFFSET_VALUE);
    vec2 mousePos = (iMouse.xy - offset) / zoom;
    ivec2 mouse = ivec2(mousePos.x, (iResolution.y - iMouse.y - 1.0 - offset.y) / zoom);

    // for square bursh,   use Manhattan distance 
    // for circular brush, use Euclidean distance
    bool isInsideBrush = SQUARE_BRUSH 
        ? abs(mouse.x - coord.x) <= int(BRUSH_SIZE) && abs(mouse.y - coord.y) <= int(BRUSH_SIZE) 
        : length(vec2(mouse - coord)) <= BRUSH_SIZE;

    if (isInsideBrush)
        return newID;

    return oldID;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec2 coord = ivec2(floor(fragCoord));

    int newID = handleInput(coord);    
    fragColor = vec4(newID, 0, 0, 0);
}
